from PIL import Image
import numpy as np
a=np.array(Image.open('first_frame.png').convert('RGB'))
# detect light gray/white thread pixels in upper area, excluding rods by brightness/saturation
for y in range(15,86,5):
 xs=[]
 for x in range(75,140):
  r,g,b=a[y,x]
  if r>110 and g>110 and b>110 and abs(int(r)-int(b))<35 and not (r>180 and g>180 and b>180):
   xs.append(x)
 # group
 groups=[]
 for x in xs:
  if not groups or x>groups[-1][-1]+1: groups.append([x])
  else: groups[-1].append(x)
 print(y, [(g[0],g[-1]) for g in groups])
